# DatePicker DatePicker ### Быстрый старт Быстрый старт ```tsx
import React, {useState} from 'react';
import { DatePicker } from '@salutejs/sdds-finai';
import { IconDone } from '@salutejs/plasma-icons';

export function App() {
    const [dateValue, setDate] = useState<Date | string | undefined>(new Date());
    const [originalDateValue, setOriginalDate] = useState<Date | string | null | undefined>(new Date());
    const [isoDateValue, setIsoDate] = useState<string | undefined>(new Date().toISOString());

    const handleChangeValue = (
        _: React.SyntheticEvent<HTMLInputElement> | null,
        value?: string,
        originalDate?: Date | string | null,
        isoDate?: string,
    ) => {
        setDate(value);
        setOriginalDate(originalDate);
        setIsoDate(isoDate);
    };

    return (
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start', gap: '3rem'}}>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.25rem'}}>
                <p>Значение date: {String(dateValue)}</p>
                <p>Значение originalDate: {String(originalDateValue)}</p>
                <p>Значение isoDate: {isoDateValue}</p>
            </div>

            <DatePicker
                onChangeValue={handleChangeValue}
                onCommitDate={console.log}
                label="Неконтролируемый DatePicker"
                format="DD.MM.YYYY"
                maskWithFormat
                lang="ru"
                contentRight={<IconDone size="s" />}
                placement="bottom"
                usePortal
            />
        </div>
    );
}
```

:::info
Сигнатура вызова onCommitDate c 6 аргументами - deprecated ```
    export type OnCommitDateCallback = (
        value: Date | string,
        error?: boolean,
        success?: boolean,
        dateInfo?: DateInfo,
        originalDate?: Date,
        isoDate?: string,
    ) => void;
```

Используйте обновленную сигнатуру с 2мя аргументами ```
    export type FormattedDateValues = {
        /**
        * Статус ошибки валидации
        */
        error?: boolean;
        /**
        * Статус успешной валидации
        */
        success?: boolean;
        /**
        * Информация о дате (для кварталов и т.д.)
        */
        dateInfo?: DateInfo;
        /**
        * Дата как экземпляр Date
        */
        originalDate?: Date;
        /**
        * Дата в формате ISO
        */
        isoDate?: string;
    };

    export type OnCommitDateCallback = (value: Date | string, formattedValues: FormattedDateValues) => void;
