        <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}>
            {sizes.map((size) => (
                <DatePickerRange
                    key={size}
                    size={size}
                    label={`Size ${size}`}
                    leftHelper="Подсказка к полю"
